11	// AscendC GroupNormSwish kernel — per-group GroupNorm + Swish activation
12	// Supports float32, float16, bfloat16
13	// Pure Vector operator: AIC+AIV cooperation
14	// Format: Abs-style with dtype dispatch in __global__ entry
15	
16	#include "kernel_operator.h"
17	
18	constexpr int32_t BUFFER_NUM = 1;
19	constexpr int32_t TILE_LENGTH = 2048;
20	constexpr int32_t DEFAULT_NUM_PHYSICAL_CORES = 20;
21	
22	// ---------------------------------------------------------------------------
23	// Inline helpers
24	// ---------------------------------------------------------------------------
25	
26	__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
27	{
28	    if (b == 0U) { return 0U; }
29	    return (a + b - 1U) / b;
30	}
31	
32	__aicore__ inline int32_t CeilDivI32(int32_t a, int32_t b)
33	{
34	    if (b == 0) { return 0; }
35	    return (a + b - 1) / b;
36	}
37	
38	__aicore__ inline int32_t MinI32(int32_t a, int32_t b)
39	{
40	    return (a < b) ? a : b;
41	}
42	
43	__aicore__ inline int32_t MaxI32(int32_t a, int32_t b)
44	{
45	    return (a > b) ? a : b;
46	}
47	
48	template <typename T>
49	__aicore__ inline void LoadGmToUb(
50	    AscendC::LocalTensor<T> &dst,
51	    AscendC::GlobalTensor<T> src,
52	    uint32_t count)
53	{
54	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
55	    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
56	    AscendC::DataCopyPad(dst, src, copyParams, padParams);
57	}
58	
59	template <typename T>
60	__aicore__ inline void StoreUbToGm(
61	    AscendC::GlobalTensor<T> dst,
62	    AscendC::LocalTensor<T> &src,
63	    uint32_t count)
64	{
65	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
66	    AscendC::DataCopyPad(dst, src, copyParams);
67	}
