69	template <typename T>
70	__aicore__ inline AscendC::RoundMode OutputRoundModeHelper()
71	{
72	    if constexpr (std::is_same_v<T, bfloat16_t>) {
73	        return AscendC::RoundMode::CAST_ROUND;
74	    }
75	    return AscendC::RoundMode::CAST_NONE;
76	}
