78	// Cast input to fp32 for stable compute. Cast handling per dtype.
79	template <typename T>
80	__aicore__ inline void PrepareInputTensor(
81	    AscendC::LocalTensor<float> &dst,
82	    AscendC::LocalTensor<T> &src,
83	    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
84	    int32_t count)
85	{
