108	template <typename T>
109	__aicore__ inline void FinalizeOutputTensor(
110	    AscendC::LocalTensor<T> &out,
111	    AscendC::LocalTensor<float> &src,
112	    int32_t count)
113	{
114	    if constexpr (!std::is_same_v<T, float>) {
115	        AscendC::Cast(out, src, OutputRoundModeHelper<T>(), count);
116	        AscendC::PipeBarrier<PIPE_V>();
