120	// =========================================================================
121	// GroupNormSwish Kernel — per-group processing
122	// =========================================================================
123	
124	template <typename dataType>
125	class GroupNormSwishKernel {
126	public:
127	    __aicore__ inline void Init(
128	        GM_ADDR input, GM_ADDR weight, GM_ADDR bias,
129	        GM_ADDR output, GM_ADDR mean_out, GM_ADDR rstd_out,
130	        int32_t total_elems, int32_t N, int32_t C, int32_t num_groups,
131	        int32_t group_c, int32_t spatial_size, int32_t group_size,
132	        int32_t total_groups, int32_t usedCoreNum, int32_t groups_per_core,
133	        float eps, float swish_scale)
134	    {
135	        total_elems_ = total_elems;
136	        N_ = N;
137	        C_ = C;
138	        num_groups_ = num_groups;
139	        group_c_ = group_c;
140	        spatial_size_ = spatial_size;
141	        group_size_ = group_size;
142	        total_groups_ = total_groups;
143	        usedCoreNum_ = usedCoreNum;
144	        groups_per_core_ = groups_per_core;
145	        eps_ = eps;
146	        swish_scale_ = swish_scale;
147	
148	        inputGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(input), static_cast<uint64_t>(total_elems));
149	        weightGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(weight), static_cast<uint64_t>(C));
150	        biasGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(bias), static_cast<uint64_t>(C));
151	        outputGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(output), static_cast<uint64_t>(total_elems));
152	        meanOutGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(mean_out),
153	                                    static_cast<uint64_t>(N) * num_groups);
154	        rstdOutGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(rstd_out),
155	                                    static_cast<uint64_t>(N) * num_groups);
156	
157	        if ASCEND_IS_AIV { InitAivBuffers(); }
158	    }
159	
160	    __aicore__ inline void InitAivBuffers()
161	    {
162	        pipe.InitBuffer(inQueue_, BUFFER_NUM, TILE_LENGTH * sizeof(dataType));
163	        pipe.InitBuffer(outQueue_, BUFFER_NUM, TILE_LENGTH * sizeof(dataType));
164	        // FP32 compute buffers (shared between Pass 1 and Pass 2)
165	        pipe.InitBuffer(xFp32Buf_, TILE_LENGTH * sizeof(float));
166	        pipe.InitBuffer(tmpBuf_, TILE_LENGTH * sizeof(float));
167	        pipe.InitBuffer(reduceBuf_, 2 * TILE_LENGTH * sizeof(uint8_t));
168	        pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
169	        // Optional cast buffers for fp16/bf16
170	        if constexpr (!std::is_same_v<dataType, float>) {
171	            pipe.InitBuffer(xCastBuf_, TILE_LENGTH * sizeof(float));
172	            pipe.InitBuffer(yCastBuf_, TILE_LENGTH * sizeof(float));
173	        }
174	        // Weight/Bias preload buffer (fp32 form, supports up to 2048 channels per group)
175	        pipe.InitBuffer(wbBuf_, kMaxGroupC * sizeof(float));
176	        pipe.InitBuffer(wExpandBuf_, TILE_LENGTH * sizeof(float));
177	        pipe.InitBuffer(bExpandBuf_, TILE_LENGTH * sizeof(float));
178	    }
179	
180	    __aicore__ inline void Process()
181	    {
182	        if ASCEND_IS_AIV {
183	            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
184	
185	            for (int localIdx = 0; localIdx < groups_per_core_; ++localIdx) {
186	                int gIdx = coreIdx * groups_per_core_ + localIdx;
187	                if (gIdx >= total_groups_) {
188	                    continue;
189	                }
190	                ProcessGroup(gIdx);
191	            }
192	        }
193	    }
194	
195	private:
196	    static constexpr int kMaxGroupC = 2048;
197	
198	    // ------------------------------------------------------------------
199	    // Process a single (n, g) group
200	    // ------------------------------------------------------------------
201	    __aicore__ inline void ProcessGroup(int gIdx)
202	    {
203	        int n = gIdx / num_groups_;
204	        int g = gIdx % num_groups_;
205	        int group_base = n * (C_ * spatial_size_) + g * group_c_ * spatial_size_;
206	        int wb_base = g * group_c_;
207	        int num_tiles = CeilDivI32(group_size_, TILE_LENGTH);
208	
209	        // Preload weight and bias (fp16 -> fp32) into UB for this group
210	        LoadWeightBiasGroup(wb_base);
211	
212	        // --- Pass 1: Accumulate sum and sum_sq ---
213	        float sumVal = 0.0f;
214	        float sumSqVal = 0.0f;
215	
216	        for (int ti = 0; ti < num_tiles; ++ti) {
217	            int offset = group_base + ti * TILE_LENGTH;
218	            int cur_len = MinI32(TILE_LENGTH, group_size_ - ti * TILE_LENGTH);
219	
220	            CopyInGroup(offset, cur_len);
221	            auto [s, sq] = ComputeTileStats(cur_len);
222	            sumVal += s;
223	            sumSqVal += sq;
224	        }
225	
226	        // Compute mean, var, rstd
227	        float invN = 1.0f / static_cast<float>(group_size_);
228	        float meanVal = sumVal * invN;
229	        float varVal = sumSqVal * invN - meanVal * meanVal;
230	        if (varVal < 0.0f) { varVal = 0.0f; }  // numerical safety
231	        float rstdVal = 1.0f / AscendC::Sqrt(varVal + eps_);
232	
233	        // Write mean and rstd to output
234	        AscendC::LocalTensor<float> meanOutLocal = sumBuf_.Get<float>();
235	        AscendC::LocalTensor<float> rstdOutLocal = reduceBuf_.Get<float>().template ReinterpretCast<float>();
236	
237	        // Use pipe and scalar-vector approach to write scalars
238	        AscendC::PipeBarrier<PIPE_ALL>();
239	
240	        // Write to mean_out and rstd_out
241	        // Use a small tmp buffer approach
242	        int meanIdx = n * num_groups_ + g;
243	        AscendC::LocalTensor<float> tmpWr = tmpBuf_.Get<float>();
244	        tmpWr.SetValue(0, meanVal);
245	        AscendC::DataCopyExtParams cp{1, static_cast<uint32_t>(sizeof(float)), 0, 0, 0};
246	        AscendC::DataCopyPad(meanOutGM_[meanIdx], tmpWr, cp);
247	
248	        AscendC::PipeBarrier<PIPE_MTE2>();
249	        AscendC::PipeBarrier<PIPE_ALL>();
250	
251	        tmpWr.SetValue(0, rstdVal);
252	        AscendC::DataCopyPad(rstdOutGM_[meanIdx], tmpWr, cp);
253	
254	        AscendC::PipeBarrier<PIPE_MTE2>();
255	        AscendC::PipeBarrier<PIPE_ALL>();
256	
257	        // --- Pass 2: Normalize + Weight/Bias + Swish ---
258	        for (int ti = 0; ti < num_tiles; ++ti) {
259	            int offset = group_base + ti * TILE_LENGTH;
260	            int cur_len = MinI32(TILE_LENGTH, group_size_ - ti * TILE_LENGTH);
261	
262	            CopyInGroup(offset, cur_len);
263	            ComputeNormalizeSwish(offset, cur_len, group_base, meanVal, rstdVal);
264	            CopyOutGroup(offset, cur_len);
265	        }
266	    }
267	
268	    // ------------------------------------------------------------------
269	    // Load weight/bias for this group into UB (fp32 form)
270	    // ------------------------------------------------------------------
271	    __aicore__ inline void LoadWeightBiasGroup(int wb_base)
272	    {
273	        wbLocal_ = wbBuf_.Get<float>();
274	
275	        // Load weight segment
276	        AscendC::LocalTensor<dataType> wbTmp = inQueue_.AllocTensor<dataType>();
277	        LoadGmToUb(wbTmp, weightGM_[wb_base], static_cast<uint32_t>(group_c_));
278	        AscendC::PipeBarrier<PIPE_MTE2>();
279	
280	        if constexpr (std::is_same_v<dataType, float>) {
281	            // Direct copy: weight values already fp32, just copy into wbLocal_
282	            AscendC::DataCopyExtParams cp{1, static_cast<uint32_t>(group_c_ * sizeof(float)), 0, 0, 0};
283	            AscendC::DataCopy(wbLocal_, wbTmp.template ReinterpretCast<float>(), cp);
284	        } else {
285	            AscendC::Cast(wbLocal_, wbTmp, AscendC::RoundMode::CAST_NONE, group_c_);
286	            AscendC::PipeBarrier<PIPE_V>();
287	        }
288	        inQueue_.FreeTensor(wbTmp);
289	        AscendC::PipeBarrier<PIPE_ALL>();
290	    }
291	
292	    // ------------------------------------------------------------------
293	    // CopyIn: load a tile of input from GM into UB
294	    // ------------------------------------------------------------------
295	    __aicore__ inline void CopyInGroup(int offset, int cur_len)
296	    {
297	        inLocal_ = inQueue_.AllocTensor<dataType>();
298	        LoadGmToUb(inLocal_, inputGM_[offset], static_cast<uint32_t>(cur_len));
299	        inQueue_.EnQue(inLocal_);
300	    }
301	
302	    // ------------------------------------------------------------------
303	    // CopyOut: write output tile from UB to GM
304	    // ------------------------------------------------------------------
305	    __aicore__ inline void CopyOutGroup(int offset, int cur_len)
306	    {
307	        AscendC::LocalTensor<dataType> outLocal = outQueue_.DeQue<dataType>();
308	        StoreUbToGm(outputGM_[offset], outLocal, static_cast<uint32_t>(cur_len));
309	        outQueue_.FreeTensor(outLocal);
310	    }
311	
312	    // ------------------------------------------------------------------
313	    // Pass 1: Compute sum and sum_sq for a tile
314	    // Returns: pair of (sum, sum_sq) as float scalars
315	    // ------------------------------------------------------------------
316	    __aicore__ inline AscendC::PipeBarrier<PIPE_ALL> ComputeTileStats(int cur_len) {
317	        // Hack: use a struct or just compute inline
318	    }
319	    // Actually, let's return a pair properly:
320	    // ------------------------------------------------------------------
321	    __aicore__ inline void ComputeTileStats(int cur_len, float &outSum, float &outSumSq)
322	    {
323	        AscendC::LocalTensor<float> xFp32 = xFp32Buf_.Get<float>();
324	        AscendC::LocalTensor<float> sqTmp = tmpBuf_.Get<float>();
325	        AscendC::LocalTensor<uint8_t> reduceTmp = reduceBuf_.Get<uint8_t>();
326	        AscendC::LocalTensor<float> sumBuf = sumBuf_.Get<float>();
327	
328	        // DeQue input
329	        AscendC::LocalTensor<dataType> inLocal = inQueue_.DeQue<dataType>();
330	        PrepareInputTensor(xFp32, inLocal, xCastBuf_, cur_len);
331	
332	        // sum
333	        AscendC::ReduceSum<float>(sumBuf, xFp32, reduceTmp, cur_len);
334	        outSum = sumBuf.GetValue(0);
335	
336	        // sum_sq: x^2 then reduce
337	        AscendC::Mul(sqTmp, xFp32, xFp32, cur_len);
338	        AscendC::PipeBarrier<PIPE_V>();
339	        AscendC::ReduceSum<float>(sumBuf, sqTmp, reduceTmp, cur_len);
340	        outSumSq = sumBuf.GetValue(0);
341	
342	        inQueue_.FreeTensor(inLocal);
343	    }
344	
345	    // ------------------------------------------------------------------
346	    // Pass 2: Normalize + Weight/Bias broadcast + Swish activation
347	    // ------------------------------------------------------------------
348	    __aicore__ inline void ComputeNormalizeSwish(
349	        int offset, int cur_len, int group_base, float meanVal, float rstdVal)
350	    {
351	        AscendC::LocalTensor<float> xFp32 = xFp32Buf_.Get<float>();
352	        AscendC::LocalTensor<float> diffNorm = tmpBuf_.Get<float>();
353	        AscendC::LocalTensor<float> wExpand = wExpandBuf_.Get<float>();
354	        AscendC::LocalTensor<float> bExpand = bExpandBuf_.Get<float>();
355	
356	        // DeQue and cast
357	        AscendC::LocalTensor<dataType> inLocal = inQueue_.DeQue<dataType>();
358	        PrepareInputTensor(xFp32, inLocal, xCastBuf_, cur_len);
359	
360	        // Allocate output
361	        AscendC::LocalTensor<dataType> outLocal = outQueue_.AllocTensor<dataType>();
362	        AscendC::LocalTensor<float> yFp32;
363	        PrepareOutputTensor(yFp32, outLocal, yCastBuf_);
364	
365	        // Step 1: Normalize = (x - mean) * rstd
366	        AscendC::Subs(diffNorm, xFp32, meanVal, cur_len);
367	        AscendC::Muls(diffNorm, diffNorm, rstdVal, cur_len);
368	        AscendC::PipeBarrier<PIPE_V>();
369	
370	        // Step 2: Expand weight/bias for this tile's positions
371	        ExpandWeightBiasForTile(offset, cur_len, group_base);
372	
373	        // Step 3: Apply weight and bias
374	        AscendC::Mul(diffNorm, diffNorm, wExpand, cur_len);
375	        AscendC::Add(diffNorm, diffNorm, bExpand, cur_len);
376	        AscendC::PipeBarrier<PIPE_V>();
377	
378	        // Step 4: Swish = x * sigmoid(swish_scale * x)
379	        // sigmoid(x) = 1 / (1 + exp(-x))
380	        // We reuse wExpand as scaled input and bExpand as exp/neg
381	        AscendC::Muls(wExpand, diffNorm, swish_scale_, cur_len);
382	        AscendC::PipeBarrier<PIPE_V>();
383	
384	        // neg = -scaled
385	        AscendC::Muls(wExpand, wExpand, -1.0f, cur_len);
386	        AscendC::PipeBarrier<PIPE_V>();
387	
388	        // exp(-scaled)
389	        AscendC::Exp(bExpand, wExpand, cur_len);
390	        AscendC::PipeBarrier<PIPE_V>();
391	
392	        // 1 + exp(-scaled)
393	        AscendC::Adds(bExpand, bExpand, 1.0f, cur_len);
394	        AscendC::PipeBarrier<PIPE_V>();
395	
396	        // reciprocal = 1 / (1 + exp(-scaled)) = sigmoid
397	        AscendC::Reciprocal(bExpand, bExpand, cur_len);
398	        AscendC::PipeBarrier<PIPE_V>();
399	
400	        // output = diffNorm * sigmoid(scaled)
401	        // Note: diffNorm still holds the (normalized * weight + bias) result
402	        AscendC::Mul(yFp32, diffNorm, bExpand, cur_len);
403	        AscendC::PipeBarrier<PIPE_V>();
404	
405	        // Cast to output dtype and write
406	        FinalizeOutputTensor(outLocal, yFp32, cur_len);
407	
408	        inQueue_.FreeTensor(inLocal);
409	        outQueue_.EnQue(outLocal);
410	    }
411	
412	    // ------------------------------------------------------------------
413	    // Expand weight/bias for the current tile
414	    // Each weight/bias value applies to spatial_size_ consecutive elements
415	    // ------------------------------------------------------------------
416	    __aicore__ inline void ExpandWeightBiasForTile(int offset, int cur_len, int group_base)
417	    {
418	        AscendC::LocalTensor<float> wExpand = wExpandBuf_.Get<float>();
419	        AscendC::LocalTensor<float> bExpand = bExpandBuf_.Get<float>();
420	        AscendC::LocalTensor<float> wbLocal = wbBuf_.Get<float>();
421	
422	        // Position of this tile within the group
423	        int groupOffset = offset - group_base;
424	
425	        int pos = 0;
426	        while (pos < cur_len) {
427	            // Which channel does position 'pos' belong to?
428	            int chIdx = (groupOffset + pos) / spatial_size_;
429	            // How many elements in this channel's block remain?
430	            int blockStart = (groupOffset + pos) % spatial_size_;
431	            int blockRemain = spatial_size_ - blockStart;
432	            int copyLen = MinI32(blockRemain, cur_len - pos);
433	
434	            float wVal = wbLocal.GetValue(chIdx);
435	            float bVal = wbLocal.GetValue(chIdx + group_c_);  // bias stored after weight
436	
437	            // Duplicate weight/bias value across the block
438	            AscendC::Duplicate<float>(wExpand[pos], wVal, copyLen);
439	            AscendC::Duplicate<float>(bExpand[pos], bVal, copyLen);
440	            AscendC::PipeBarrier<PIPE_V>();
441	
442	            pos += copyLen;
443	        }
444	    }
445	
446	private:
447	    // Tiling params
448	    int32_t total_elems_ = 0;
449	    int32_t N_ = 0;
450	    int32_t C_ = 0;
451	    int32_t num_groups_ = 0;
452	    int32_t group_c_ = 0;
453	    int32_t spatial_size_ = 0;
454	    int32_t group_size_ = 0;
455	    int32_t total_groups_ = 0;
456	    int32_t usedCoreNum_ = 0;
457	    int32_t groups_per_core_ = 0;
458	    float eps_ = 0.0f;
459	    float swish_scale_ = 1.0f;
460	
461	    // GM tensors
462	    AscendC::GlobalTensor<dataType> inputGM_;
463	    AscendC::GlobalTensor<dataType> weightGM_;
464	    AscendC::GlobalTensor<dataType> biasGM_;
465	    AscendC::GlobalTensor<dataType> outputGM_;
466	    AscendC::GlobalTensor<float> meanOutGM_;
467	    AscendC::GlobalTensor<float> rstdOutGM_;
468	
469	    // TPipe and Queues
470	    AscendC::TPipe pipe;
471	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueue_;
472	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueue_;
473	
474	    // TBufs for compute
475	    AscendC::TBuf<AscendC::TPosition::VECCALC> xFp32Buf_;
476	    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf_;
477	    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_;
478	    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
479	    AscendC::TBuf<AscendC::TPosition::VECCALC> xCastBuf_;
480	    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;
481	    AscendC::TBuf<AscendC::TPosition::VECCALC> wbBuf_;         // weight+bias fp32 preload
482	    AscendC::TBuf<AscendC::TPosition::VECCALC> wExpandBuf_;     // expanded weight per tile
483	    AscendC::TBuf<AscendC::TPosition::VECCALC> bExpandBuf_;     // expanded bias per tile
484	
485	    // Local tensors
486	    AscendC::LocalTensor<dataType> inLocal_;
487	    AscendC::LocalTensor<float> wbLocal_;
488	};
