494	template <typename... ExtraArgs>
495	__aicore__ inline void DispatchGroupNormSwish(
496	    GM_ADDR input, GM_ADDR weight, GM_ADDR bias,
497	    GM_ADDR output, GM_ADDR mean_out, GM_ADDR rstd_out,
498	    int32_t total_elems, int32_t N, int32_t C, int32_t num_groups,
499	    int32_t group_c, int32_t spatial_size, int32_t group_size,
500	    int32_t total_groups, int32_t usedCoreNum, int32_t groups_per_core,
501	    int64_t dtypeFlag, float eps, float swish_scale)
502	{
503	    if (dtypeFlag == 0) {
504	        GroupNormSwishKernel<float> kernel;
505	        kernel.Init(input, weight, bias, output, mean_out, rstd_out,
506	                    total_elems, N, C, num_groups,
507	                    group_c, spatial_size, group_size,
508	                    total_groups, usedCoreNum, groups_per_core,
509	                    eps, swish_scale);
510	        kernel.Process();
511	    } else if (dtypeFlag == 1) {
512	        GroupNormSwishKernel<half> kernel;
513	        kernel.Init(input, weight, bias, output, mean_out, rstd_out,
514	                    total_elems, N, C, num_groups,
515	                    group_c, spatial_size, group_size,
516	                    total_groups, usedCoreNum, groups_per_core,
517	                    eps, swish_scale);
518	        kernel.Process();
519	    } else {
520	        GroupNormSwishKernel<bfloat16_t> kernel;
521	        kernel.Init(input, weight, bias, output, mean_out, rstd_out,
522	                    total_elems, N, C, num_groups,
523	                    group_c, spatial_size, group_size,
524	                    total_groups, usedCoreNum, groups_per_core,
525	                    eps, swish_scale);
526	        kernel.Process();
527	    }
528	}
