6	// MoeComputeExpertTokens op_host — tiling calculation + EXEC_KERNEL_CMD launch
7	
8	#include <algorithm>
9	#include <cstdint>
10	
11	#include <torch/extension.h>
12	
13	#include "torch_kernel_helper.h"
14	#include "tiling/platform/platform_ascendc.h"
15	
16	#include "aclrtlaunch_moe_compute_expert_tokens.h"
17	
18	// ---------------------------------------------------------------------------
19	// Constants
20	// ---------------------------------------------------------------------------
21	
22	constexpr int32_t NUM_PHYSICAL_CORES = 20;
23	constexpr int32_t DEFAULT_TILE_SIZE = 256;
24	constexpr int32_t CACHE_LINE_ALIGN = 512;  // 512 bytes
25	
26	// ---------------------------------------------------------------------------
27	// Host function
28	// ---------------------------------------------------------------------------
29	
30	namespace ascend_kernel {
31	
32	at::Tensor moe_compute_expert_tokens(
33	    const at::Tensor &sorted_expert_for_source_row,
34	    int64_t num_expert)
35	{
36	    // Input validation
37	    TORCH_CHECK(sorted_expert_for_source_row.dim() == 1,
38	                "sorted_expert_for_source_row must be 1D");
39	    TORCH_CHECK(sorted_expert_for_source_row.scalar_type() == at::kInt,
40	                "sorted_expert_for_source_row must be int32");
41	    TORCH_CHECK(sorted_expert_for_source_row.is_contiguous(),
42	                "sorted_expert_for_source_row must be contiguous");
43	    TORCH_CHECK(num_expert > 0,
44	                "num_expert must be > 0");
45	
46	    int64_t N = sorted_expert_for_source_row.size(0);
47	
48	    // Tiling calculation
49	    auto ascendcPlatform = platform_ascendc::PlatformAscendCMgr::GetInstance();
50	    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
51	    if (coreNum <= 0) {
52	        coreNum = NUM_PHYSICAL_CORES;
53	    }
54	    // Use the minimum of available cores and what we actually need
55	    int64_t usedCoreNum = (N + DEFAULT_TILE_SIZE - 1) / DEFAULT_TILE_SIZE;
56	    usedCoreNum = std::max<int64_t>(1, std::min<int64_t>(usedCoreNum, coreNum));
57	    if (usedCoreNum < 1) { usedCoreNum = 1; }
58	
59	    int64_t NPerCore = (N + usedCoreNum - 1) / usedCoreNum;
60	
61	    // Tile size based on UB
62	    uint64_t ubSize = 0;
63	    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
64	    // UB budget: we need tileSize * sizeof(int32) for input (double buffer x1),
65	    // plus num_expert * sizeof(int32) for histogram.
66	    // Safe: use ~80% of UB capacity
67	    int64_t maxTileFromUb = static_cast<int64_t>(
68	        (ubSize * 8 / 10 - static_cast<uint64_t>(num_expert) * sizeof(int32_t))
69	        / sizeof(int32_t));
70	    int64_t tileSize = std::min<int64_t>(DEFAULT_TILE_SIZE,
71	        std::max<int64_t>(32, maxTileFromUb));
72	    // Align to 32 elements for DataCopyPad compatibility
73	    tileSize = (tileSize / 32) * 32;
74	    if (tileSize < 32) { tileSize = 32; }
75	
76	    // Workspace: [usedCoreNum, num_expert] int32
77	    int64_t workspaceElems = usedCoreNum * num_expert;
78	    at::Tensor workspace = at::empty(
79	        {workspaceElems},
80	        sorted_expert_for_source_row.options().dtype(at::kInt));
81	
82	    // Output
83	    at::Tensor expert_tokens = at::empty(
84	        {num_expert},
85	        sorted_expert_for_source_row.options().dtype(at::kInt));
86	
87	    // EXEC_KERNEL_CMD requires all parameters as left-values
88	    int64_t totalN = N;
89	    int64_t numExpert = num_expert;
90	    int64_t usedCoreNumLv = usedCoreNum;
91	    int64_t NPerCoreLv = NPerCore;
92	    int64_t tileSizeLv = tileSize;
93	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
94	
95	    EXEC_KERNEL_CMD(moe_compute_expert_tokens, blockDim,
96	                    sorted_expert_for_source_row, expert_tokens, workspace,
97	                    totalN, numExpert, usedCoreNumLv, NPerCoreLv, tileSizeLv);
98	
99	    return expert_tokens;
100	}
