6	// AscendC MoeComputeExpertTokens kernel
7	// Multi-core histogram (bincount) + merge + prefix sum (cumsum)
8	// Data type: int32 only
9	
10	#include "kernel_operator.h"
11	
12	using namespace AscendC;
13	
14	constexpr int32_t BUFFER_NUM = 1;
15	
16	// ---------------------------------------------------------------------------
17	// Helper: load tile from GM to UB, return the tile length (may be tail-short)
18	// ---------------------------------------------------------------------------
19	template <typename T>
20	__aicore__ inline void LoadGmToUb(
21	    LocalTensor<T> &dst,
22	    const GlobalTensor<T> &src,
23	    int32_t count)
24	{
25	    if (count <= 0) { return; }
26	    DataCopyExtParams copyParams{1, static_cast<uint32_t>(count * sizeof(T)), 0, 0, 0};
27	    DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
28	    DataCopyPad(dst, src, copyParams, padParams);
29	}
30	
31	template <typename T>
32	__aicore__ inline void StoreUbToGm(
33	    const GlobalTensor<T> &dst,
34	    const LocalTensor<T> &src,
35	    int32_t count)
36	{
37	    if (count <= 0) { return; }
38	    DataCopyExtParams copyParams{1, static_cast<uint32_t>(count * sizeof(T)), 0, 0, 0};
39	    DataCopyPad(dst, src, copyParams);
40	}
