42	// =========================================================================
43	// MoeComputeExpertTokens Kernel
44	// =========================================================================
45	
46	class KernelMoeComputeExpertTokens {
47	public:
48	    __aicore__ inline void Init(
49	        GM_ADDR sorted_expert,
50	        GM_ADDR expert_tokens,
51	        GM_ADDR workspace,
52	        int64_t N,
53	        int64_t num_expert,
54	        int64_t usedCoreNum,
55	        int64_t N_per_core,
56	        int64_t tile_size)
57	    {
58	        this->totalN = N;
59	        this->numExpert = num_expert;
60	        this->usedCoreNum = usedCoreNum;
61	        this->NPerCore = N_per_core;
62	        this->tileSize = tile_size;
63	
64	        // Compute this core's element range
65	        coreIdx = static_cast<int64_t>(GetBlockIdx());
66	        elemStart = coreIdx * NPerCore;
67	        elemEnd = (elemStart + NPerCore > totalN) ? totalN : (elemStart + NPerCore);
68	        curElems = elemEnd - elemStart;
69	
70	        // Set up global tensors
71	        sortedExpertGm.SetGlobalBuffer(
72	            reinterpret_cast<__gm__ int32_t *>(sorted_expert),
73	            static_cast<uint64_t>(totalN));
74	        expertTokensGm.SetGlobalBuffer(
75	            reinterpret_cast<__gm__ int32_t *>(expert_tokens),
76	            static_cast<uint64_t>(numExpert));
77	        workspaceGm.SetGlobalBuffer(
78	            reinterpret_cast<__gm__ int32_t *>(workspace),
79	            static_cast<uint64_t>(usedCoreNum * numExpert));
80	
81	        // Allocate UB buffers
82	        pipe.InitBuffer(inQueue, BUFFER_NUM, static_cast<uint32_t>(tileSize * sizeof(int32_t)));
83	        pipe.InitBuffer(histBuf, static_cast<uint32_t>(numExpert * sizeof(int32_t)));
84	    }
85	
86	    __aicore__ inline void Process()
87	    {
88	        // Initialize histogram to 0
89	        histLocal = histBuf.Get<int32_t>();
90	        Duplicate(histLocal, (int32_t)0, static_cast<int32_t>(numExpert));
91	
92	        // === Phase 1: Per-core histogram ===
93	        numTiles = (curElems + tileSize - 1) / tileSize;
94	
95	        for (int64_t tileIdx = 0; tileIdx < numTiles; ++tileIdx) {
96	            int64_t tileStart = tileIdx * tileSize;
97	            int64_t tileEnd = (tileStart + tileSize > curElems) ? curElems : (tileStart + tileSize);
98	            int32_t curTileLen = static_cast<int32_t>(tileEnd - tileStart);
99	
100	            // CopyIn: load input tile from GM to UB
101	            inLocal = inQueue.AllocTensor<int32_t>();
102	            GlobalTensor<int32_t> inputGmSlice = sortedExpertGm[elemStart + tileStart];
103	            LoadGmToUb(inLocal, inputGmSlice, curTileLen);
104	            inQueue.EnQue(inLocal);
105	
106	            // Compute: process tile, update histogram
107	            inLocal = inQueue.DeQue<int32_t>();
108	
109	            // Process each element in the tile; the outer parallelism is at the
110	            // core level (20 cores), so a scalar tile loop is efficient.
111	            for (int32_t i = 0; i < curTileLen; ++i) {
112	                int32_t expertIdx = inLocal(i);
113	                if (expertIdx >= 0 && expertIdx < static_cast<int32_t>(numExpert)) {
114	                    histLocal(expertIdx) = histLocal(expertIdx) + (int32_t)1;
115	                }
116	            }
117	            inQueue.FreeTensor(inLocal);
118	        }
119	
120	        // Write local histogram to workspace
121	        int64_t wsOffset = coreIdx * numExpert;
122	        GlobalTensor<int32_t> wsSlice = workspaceGm[wsOffset];
123	        StoreUbToGm(wsSlice, histLocal, static_cast<int32_t>(numExpert));
124	        PipeBarrier<PIPE_ALL>();
125	
126	        // === Phase 2: Core 0 merges ===
127	        // SyncAll: wait for all cores to write their histograms to workspace
128	        SyncAll();
129	
130	        if (coreIdx == 0) {
131	            // Allocate merge buffer
132	            pipe.InitBuffer(mergeBuf, static_cast<uint32_t>(numExpert * sizeof(int32_t)));
133	            pipe.InitBuffer(readBuf, static_cast<uint32_t>(numExpert * sizeof(int32_t)));
134	
135	            mergeLocal = mergeBuf.Get<int32_t>();
136	            readLocal = readBuf.Get<int32_t>();
137	
138	            // Initialize merge to zero
139	            Duplicate(mergeLocal, (int32_t)0, static_cast<int32_t>(numExpert));
140	
141	            // Read and sum all partial histograms from workspace
142	            for (int64_t c = 0; c < usedCoreNum; ++c) {
143	                int64_t wsCoreOffset = c * numExpert;
144	                GlobalTensor<int32_t> wsCoreSlice = workspaceGm[wsCoreOffset];
145	                LoadGmToUb(readLocal, wsCoreSlice, static_cast<int32_t>(numExpert));
146	                PipeBarrier<PIPE_MTE2>();
147	                PipeBarrier<PIPE_V>();
148	                Add(mergeLocal, mergeLocal, readLocal, static_cast<int32_t>(numExpert));
149	                PipeBarrier<PIPE_V>();
150	            }
151	
152	            // Prefix sum (cumsum) in-place on mergeLocal
153	            // This is inherently sequential: output[i] = output[i-1] + mergeLocal[i]
154	            PipeBarrier<PIPE_ALL>();
155	            for (int32_t i = 1; i < static_cast<int32_t>(numExpert); ++i) {
156	                mergeLocal(i) = mergeLocal(i - 1) + mergeLocal(i);
157	            }
158	            PipeBarrier<PIPE_ALL>();
159	
160	            // Write output to GM
161	            StoreUbToGm(expertTokensGm, mergeLocal, static_cast<int32_t>(numExpert));
162	            PipeBarrier<PIPE_ALL>();
163	        }
164	    }
165	
166	private:
167	    AscendC::TPipe pipe;
168	
169	    // Global tensors
170	    GlobalTensor<int32_t> sortedExpertGm;
171	    GlobalTensor<int32_t> expertTokensGm;
172	    GlobalTensor<int32_t> workspaceGm;
173	
174	    // UB buffers
175	    TQue<QuePosition::VECIN, BUFFER_NUM> inQueue;
176	    TBuf<TPosition::VECCALC> histBuf;
177	    TBuf<TPosition::VECCALC> mergeBuf;
178	    TBuf<TPosition::VECCALC> readBuf;
179	
180	    // Local tensors
181	    LocalTensor<int32_t> inLocal;
182	    LocalTensor<int32_t> histLocal;
183	    LocalTensor<int32_t> mergeLocal;
184	    LocalTensor<int32_t> readLocal;
185	
186	    // Parameters
187	    int64_t totalN = 0;
188	    int64_t numExpert = 0;
189	    int64_t usedCoreNum = 0;
190	    int64_t NPerCore = 0;
191	    int64_t tileSize = 0;
192	    int64_t coreIdx = 0;
193	    int64_t elemStart = 0;
194	    int64_t elemEnd = 0;
195	    int64_t curElems = 0;
196	    int64_t numTiles = 0;
197	};
