// AscendC RotaryMul kernel
// Operator: npu_rotary_mul (Rotary Position Embedding Multiply)
// Computes: output = input * r1 + rotated * r2
//   half mode:       rotated = concat(-input[:,half_d:], input[:,:half_d])
//   interleave mode: rotated[i] = interleave(-input[1::2], input[0::2])
// All compute in FP32 for numerical stability.
// Pure Vector operator, no Cube.

#include "kernel_operator.h"

using namespace AscendC;

constexpr int32_t BUFFER_NUM = 1;
constexpr int32_t MAX_D = 256;

// ---------------------------------------------------------------------------
// Data movement helpers
// ---------------------------------------------------------------------------

template <typename T>
__aicore__ inline void LoadGmToUb(
    LocalTensor<T> &dst,
    const GlobalTensor<T> &src,
    int32_t count)
{
    if (count <= 0) { return; }
    DataCopyExtParams copyParams{1, static_cast<uint32_t>(count * sizeof(T)), 0, 0, 0};
    DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    const GlobalTensor<T> &dst,
    const LocalTensor<T> &src,
    int32_t count)
{
    if (count <= 0) { return; }
    DataCopyExtParams copyParams{1, static_cast<uint32_t>(count * sizeof(T)), 0, 0, 0};
    DataCopyPad(dst, src, copyParams);
}

// ---------------------------------------------------------------------------
// Cast helpers for FP16/BF16 → FP32 → FP16/BF16
// ---------------------------------------------------------------------------

template <typename T>
constexpr RoundMode OutputCastMode()
{
    if constexpr (std::is_same_v<T, bfloat16_t>) {
        return RoundMode::CAST_ROUND;
    }
    return RoundMode::CAST_NONE;
}

template <typename T>
__aicore__ inline void CastInputToFp32(
    LocalTensor<float> &dst,
    const LocalTensor<T> &src,
    TBuf<TPosition::VECCALC> &castBuf,
    int32_t count)
{
    if constexpr (std::is_same_v<T, float>) {
        dst = src.template ReinterpretCast<float>();
    } else {
        dst = castBuf.Get<float>();
        Cast(dst, src, RoundMode::CAST_NONE, count);
        PipeBarrier<PIPE_V>();
    }
}

template <typename T>
__aicore__ inline void CastFp32ToOutput(
    LocalTensor<T> &dst,
    const LocalTensor<float> &src,
    int32_t count)
{
    if constexpr (!std::is_same_v<T, float>) {
        Cast(dst, src, OutputCastMode<T>(), count);
        PipeBarrier<PIPE_V>();
    }
}

// ---------------------------------------------------------------------------
// RotaryMul Kernel
// ---------------------------------------------------------------------------

template <typename dataType>
class KernelRotaryMul {
public:
    __aicore__ inline void Init(
        GM_ADDR input, GM_ADDR r1, GM_ADDR r2, GM_ADDR output,
        int64_t total_rows, int64_t D, int64_t half_d,
        int64_t rows_per_core, int64_t ub_tile_rows,
        int64_t rotary_mode)
    {
        totalRows_ = total_rows;
        D_ = D;
        halfD_ = half_d;
        rowsPerCore_ = rows_per_core;
        ubTileRows_ = ub_tile_rows;
        rotaryMode_ = rotary_mode;

        coreIdx_ = static_cast<int64_t>(GetBlockIdx());
        rowStart_ = coreIdx_ * rowsPerCore_;
        rowEnd_ = (rowStart_ + rowsPerCore_ > totalRows_)
                    ? totalRows_ : (rowStart_ + rowsPerCore_);
        curCoreRows_ = rowEnd_ - rowStart_;

        // Bind GM tensors
        int64_t totalElems = totalRows_ * D_;
        inputGm_.SetGlobalBuffer(
            reinterpret_cast<__gm__ dataType *>(input),
            static_cast<uint64_t>(totalElems));
        r1Gm_.SetGlobalBuffer(
            reinterpret_cast<__gm__ dataType *>(r1),
            static_cast<uint64_t>(totalElems));
        r2Gm_.SetGlobalBuffer(
            reinterpret_cast<__gm__ dataType *>(r2),
            static_cast<uint64_t>(totalElems));
        outputGm_.SetGlobalBuffer(
            reinterpret_cast<__gm__ dataType *>(output),
            static_cast<uint64_t>(totalElems));

        // Initialize UB buffers
        int64_t tileElems = ubTileRows_ * D_;
        int64_t tileHalfElems = ubTileRows_ * halfD_;

        pipe.InitBuffer(inQueue_, BUFFER_NUM,
                        static_cast<uint32_t>(tileElems * sizeof(dataType)));
        pipe.InitBuffer(outQueue_, BUFFER_NUM,
                        static_cast<uint32_t>(tileElems * sizeof(dataType)));

        // FP32 compute buffers
        pipe.InitBuffer(inpFp32Buf_, static_cast<uint32_t>(tileElems * sizeof(float)));
        pipe.InitBuffer(r1Fp32Buf_, static_cast<uint32_t>(tileElems * sizeof(float)));
        pipe.InitBuffer(r2Fp32Buf_, static_cast<uint32_t>(tileElems * sizeof(float)));
        pipe.InitBuffer(rotFp32Buf_, static_cast<uint32_t>(tileElems * sizeof(float)));

        // Cast buffer (shared for all casts)
        if constexpr (!std::is_same_v<dataType, float>) {
            pipe.InitBuffer(castBuf_, static_cast<uint32_t>(tileElems * sizeof(float)));
        }

        // Auxiliary buffers for interleave mode
        if (rotaryMode_ == 1) {
            pipe.InitBuffer(evenBuf_, static_cast<uint32_t>(tileHalfElems * sizeof(float)));
            pipe.InitBuffer(oddBuf_, static_cast<uint32_t>(tileHalfElems * sizeof(float)));
        }
    }

    __aicore__ inline void Process()
    {
        if (curCoreRows_ <= 0) { return; }

        int64_t numTiles = (curCoreRows_ + ubTileRows_ - 1) / ubTileRows_;

        for (int64_t tileIdx = 0; tileIdx < numTiles; ++tileIdx) {
            int64_t tileStart = tileIdx * ubTileRows_;
            int64_t tileEnd = (tileStart + ubTileRows_ > curCoreRows_)
                                ? curCoreRows_ : (tileStart + ubTileRows_);
            int32_t curRows = static_cast<int32_t>(tileEnd - tileStart);
            int32_t curElems = curRows * static_cast<int32_t>(D_);
            int32_t curHalfElems = curRows * static_cast<int32_t>(halfD_);
            int64_t globalOffset = (rowStart_ + tileStart) * D_;

            CopyIn(globalOffset, curElems, curRows);
            Compute(curRows, curElems, curHalfElems, globalOffset);
            CopyOut(globalOffset, curElems, curRows);
        }
    }

private:
    // ------------------------------------------------------------------
    // CopyIn: load input tile from GM to UB, cast to FP32
    // ------------------------------------------------------------------
    __aicore__ inline void CopyIn(
        int64_t globalOffset, int32_t curElems, int32_t curRows)
    {
        // Load input
        {
            LocalTensor<dataType> inTemp = inQueue_.AllocTensor<dataType>();
            LoadGmToUb(inTemp, inputGm_[globalOffset], curElems);
            inQueue_.EnQue(inTemp);
            LocalTensor<dataType> inDeq = inQueue_.DeQue<dataType>();
            CastInputToFp32(inpFp32Local_, inDeq, castBuf_, curElems);
            inQueue_.FreeTensor(inDeq);
        }
        PipeBarrier<PIPE_ALL>();

        // Load r1
        {
            LocalTensor<dataType> r1Temp = inQueue_.AllocTensor<dataType>();
            LoadGmToUb(r1Temp, r1Gm_[globalOffset], curElems);
            inQueue_.EnQue(r1Temp);
            LocalTensor<dataType> r1Deq = inQueue_.DeQue<dataType>();
            CastInputToFp32(r1Fp32Local_, r1Deq, castBuf_, curElems);
            inQueue_.FreeTensor(r1Deq);
        }
        PipeBarrier<PIPE_ALL>();

        // Load r2
        {
            LocalTensor<dataType> r2Temp = inQueue_.AllocTensor<dataType>();
            LoadGmToUb(r2Temp, r2Gm_[globalOffset], curElems);
            inQueue_.EnQue(r2Temp);
            LocalTensor<dataType> r2Deq = inQueue_.DeQue<dataType>();
            CastInputToFp32(r2Fp32Local_, r2Deq, castBuf_, curElems);
            inQueue_.FreeTensor(r2Deq);
        }
        PipeBarrier<PIPE_ALL>();

        // Get FP32 TBuf pointers
        inpFp32Local_ = inpFp32Buf_.Get<float>();
        r1Fp32Local_ = r1Fp32Buf_.Get<float>();
        r2Fp32Local_ = r2Fp32Buf_.Get<float>();
        rotFp32Local_ = rotFp32Buf_.Get<float>();
    }

    // ------------------------------------------------------------------
    // Compute: build rotated, compute output = input*r1 + rotated*r2
    // ------------------------------------------------------------------
    __aicore__ inline void Compute(
        int32_t curRows, int32_t curElems, int32_t curHalfElems,
        int64_t globalOffset)
    {
        if (rotaryMode_ == 0) {
            ComputeHalfMode(curRows, curElems, curHalfElems, globalOffset);
        } else {
            ComputeInterleaveMode(curRows, curElems, curHalfElems);
        }
        PipeBarrier<PIPE_ALL>();
    }

    // ------------------------------------------------------------------
    // Half mode: rotated = concat(-input[halfD:], input[:halfD])
    // ------------------------------------------------------------------
    __aicore__ inline void ComputeHalfMode(
        int32_t curRows, int32_t curElems, int32_t curHalfElems,
        int64_t globalOffset)
    {
        int32_t D32 = static_cast<int32_t>(D_);
        int32_t halfD32 = static_cast<int32_t>(halfD_);

        // Build rotated from input GM directly (avoids UB-to-UB slice issues)
        // First half of rotated = -input[halfD:]
        {
            LocalTensor<dataType> inpTemp = inQueue_.AllocTensor<dataType>();
            LoadGmToUb(inpTemp,
                       inputGm_[globalOffset + halfD32],
                       curHalfElems);
            inQueue_.EnQue(inpTemp);
            LocalTensor<dataType> inpDeq = inQueue_.DeQue<dataType>();
            LocalTensor<float> castTmp;
            CastInputToFp32(castTmp, inpDeq, castBuf_, curHalfElems);
            inQueue_.FreeTensor(inpDeq);
            // Negate
            Muls(rotFp32Local_, castTmp, -1.0f, curHalfElems);
            PipeBarrier<PIPE_V>();
        }

        // Second half of rotated = input[:halfD]
        {
            LocalTensor<dataType> inpTemp = inQueue_.AllocTensor<dataType>();
            LoadGmToUb(inpTemp,
                       inputGm_[globalOffset],
                       curHalfElems);
            inQueue_.EnQue(inpTemp);
            LocalTensor<dataType> inpDeq = inQueue_.DeQue<dataType>();
            LocalTensor<float> castTmp;
            CastInputToFp32(castTmp, inpDeq, castBuf_, curHalfElems);
            inQueue_.FreeTensor(inpDeq);

            // Use DataCopy to write second half
            DataCopyExtParams cp{1, static_cast<uint32_t>(curHalfElems * sizeof(float)), 0, 0, 0};
            // Write to rotFp32Local_[halfD32:]
            LocalTensor<float> rotSecondHalf = rotFp32Local_[halfD32];
            DataCopy(rotSecondHalf, castTmp, cp);
            PipeBarrier<PIPE_V>();
        }

        // Compute: output = input * r1 + rotated * r2
        Mul(r1Fp32Local_, inpFp32Local_, r1Fp32Local_, curElems);
        PipeBarrier<PIPE_V>();
        Mul(r2Fp32Local_, rotFp32Local_, r2Fp32Local_, curElems);
        PipeBarrier<PIPE_V>();
        Add(rotFp32Local_, r1Fp32Local_, r2Fp32Local_, curElems);
        PipeBarrier<PIPE_V>();
    }

    // ------------------------------------------------------------------
    // Interleave mode: GatherMask extract + negate + merge
    // ------------------------------------------------------------------
    __aicore__ inline void ComputeInterleaveMode(
        int32_t curRows, int32_t curElems, int32_t curHalfElems)
    {
        int32_t halfD32 = static_cast<int32_t>(halfD_);
        int32_t D32 = static_cast<int32_t>(D_);

        LocalTensor<float> evenTmp = evenBuf_.Get<float>();
        LocalTensor<float> oddTmp = oddBuf_.Get<float>();

        // Extract even elements (indices 0,2,...) = pattern "P0101"
        GatherMask(evenTmp, inpFp32Local_, "0101");
        PipeBarrier<PIPE_V>();

        // Extract odd elements (indices 1,3,...) = pattern "P1010"
        GatherMask(oddTmp, inpFp32Local_, "1010");
        PipeBarrier<PIPE_V>();

        // Negate odds
        Muls(oddTmp, oddTmp, -1.0f, curHalfElems);
        PipeBarrier<PIPE_V>();

        // Merge: rotFp32[2*i] = oddTmp[i], rotFp32[2*i+1] = evenTmp[i]
        // Since D is small (<=128), and we need strided write access
        // which has no direct vector API, use element-wise merge.
        for (int32_t r = 0; r < curRows; ++r) {
            int32_t rowOffD = r * D32;
            int32_t rowOffHalf = r * halfD32;
            for (int32_t i = 0; i < halfD32; ++i) {
                rotFp32Local_(rowOffD + 2 * i) = oddTmp(rowOffHalf + i);
                rotFp32Local_(rowOffD + 2 * i + 1) = evenTmp(rowOffHalf + i);
            }
        }
        PipeBarrier<PIPE_ALL>();

        // Compute: output = input * r1 + rotated * r2
        Mul(r1Fp32Local_, inpFp32Local_, r1Fp32Local_, curElems);
        PipeBarrier<PIPE_V>();
        Mul(r2Fp32Local_, rotFp32Local_, r2Fp32Local_, curElems);
        PipeBarrier<PIPE_V>();
        Add(rotFp32Local_, r1Fp32Local_, r2Fp32Local_, curElems);
        PipeBarrier<PIPE_V>();
    }

    // ------------------------------------------------------------------
    // CopyOut: cast to output dtype, write to GM
    // ------------------------------------------------------------------
    __aicore__ inline void CopyOut(
        int64_t globalOffset, int32_t curElems, int32_t curRows)
    {
        // rotFp32Local_ holds the result in FP32
        LocalTensor<dataType> outTemp = outQueue_.AllocTensor<dataType>();

        if constexpr (std::is_same_v<dataType, float>) {
            // Direct copy: results are already fp32, just copy
            DataCopyExtParams cp{1, static_cast<uint32_t>(curElems * sizeof(float)), 0, 0, 0};
            DataCopy(outTemp.template ReinterpretCast<float>(),
                     rotFp32Local_, cp);
        } else {
            // Cast fp32 → output dtype
            CastFp32ToOutput(outTemp, rotFp32Local_, curElems);
        }

        outQueue_.EnQue(outTemp);
        LocalTensor<dataType> outDeq = outQueue_.DeQue<dataType>();
        StoreUbToGm(outputGm_[globalOffset], outDeq, curElems);
        outQueue_.FreeTensor(outDeq);
        PipeBarrier<PIPE_ALL>();
    }

    // Parameters
    int64_t totalRows_ = 0;
    int64_t D_ = 0;
    int64_t halfD_ = 0;
    int64_t rowsPerCore_ = 0;
    int64_t ubTileRows_ = 0;
    int64_t rotaryMode_ = 0;
    int64_t coreIdx_ = 0;
    int64_t rowStart_ = 0;
    int64_t rowEnd_ = 0;
    int64_t curCoreRows_ = 0;

    // GM tensors
    GlobalTensor<dataType> inputGm_;
    GlobalTensor<dataType> r1Gm_;
    GlobalTensor<dataType> r2Gm_;
    GlobalTensor<dataType> outputGm_;

    // Pipe and Queues
    TPipe pipe;
    TQue<QuePosition::VECIN, BUFFER_NUM> inQueue_;
    TQue<QuePosition::VECOUT, BUFFER_NUM> outQueue_;

    // TBufs for compute (FP32)
    TBuf<TPosition::VECCALC> inpFp32Buf_;
    TBuf<TPosition::VECCALC> r1Fp32Buf_;
    TBuf<TPosition::VECCALC> r2Fp32Buf_;
    TBuf<TPosition::VECCALC> rotFp32Buf_;
    TBuf<TPosition::VECCALC> castBuf_;      // for fp16/bf16 casts
    TBuf<TPosition::VECCALC> evenBuf_;      // for interleave even extraction
    TBuf<TPosition::VECCALC> oddBuf_;       // for interleave odd extraction

    // Local tensors
    LocalTensor<float> inpFp32Local_;
    LocalTensor<float> r1Fp32Local_;
    LocalTensor<float> r2Fp32Local_;
    LocalTensor<float> rotFp32Local_;
};

// =========================================================================
// Dtype dispatch helper
// =========================================================================

template <typename... ExtraArgs>
__aicore__ inline void DispatchRotaryMul(
    GM_ADDR input, GM_ADDR r1, GM_ADDR r2, GM_ADDR output,
    int64_t total_rows, int64_t D, int64_t half_d,
    int64_t rows_per_core, int64_t ub_tile_rows,
    int64_t rotary_mode, int64_t dtype_flag)
{
    if (dtype_flag == 0) {
        KernelRotaryMul<float> kernel;
        kernel.Init(input, r1, r2, output,
                    total_rows, D, half_d,
                    rows_per_core, ub_tile_rows,
                    rotary_mode);
        kernel.Process();
    } else if (dtype_flag == 1) {
        KernelRotaryMul<half> kernel;
        kernel.Init(input, r1, r2, output,
                    total_rows, D, half_d,
                    rows_per_core, ub_tile_rows,
                    rotary_mode);
        kernel.Process();
    } else {
        KernelRotaryMul<bfloat16_t> kernel;
        kernel.Init(input, r1, r2, output,
                    total_rows, D, half_d,
                    rows_per_core, ub_tile_rows,
                    rotary_mode);
        kernel.Process();
    }
}

// =========================================================================
// Kernel entry points — one per dtype
// dtype_flag: 0=fp32, 1=fp16, 2=bf16
// =========================================================================

extern "C" __global__ __aicore__ void rotary_mul(
    GM_ADDR input, GM_ADDR r1, GM_ADDR r2, GM_ADDR output,
    int64_t total_rows, int64_t D, int64_t half_d,
    int64_t rows_per_core, int64_t ub_tile_rows,
    int64_t rotary_mode, int64_t dtype_flag)
{
    DispatchRotaryMul(
        input, r1, r2, output,
        total_rows, D, half_d,
        rows_per_core, ub_tile_rows,
        rotary_mode, dtype_flag);
}
