// RotaryMul op_host — tiling calculation + EXEC_KERNEL_CMD launch

#include <algorithm>
#include <cstdint>

#include <torch/extension.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_rotary_mul.h"

namespace ascend_kernel {

// ---------------------------------------------------------------------------
// Helper: integer ceil division
// ---------------------------------------------------------------------------

static inline int64_t CeilDiv(int64_t a, int64_t b)
{
    if (b <= 0) { return 0; }
    return (a + b - 1) / b;
}

// ---------------------------------------------------------------------------
// Host function: npu_rotary_mul
// ---------------------------------------------------------------------------

at::Tensor rotary_mul(
    const at::Tensor &input,
    const at::Tensor &r1,
    const at::Tensor &r2,
    std::string rotary_mode)
{
    // --- Input validation ---
    TORCH_CHECK(input.dim() == 4,
                "rotary_mul: input must be 4D (B, H, S, D)");
    TORCH_CHECK(input.scalar_type() == r1.scalar_type() &&
                input.scalar_type() == r2.scalar_type(),
                "rotary_mul: input, r1, r2 must have same dtype");
    TORCH_CHECK(input.is_contiguous() && r1.is_contiguous() && r2.is_contiguous(),
                "rotary_mul: all inputs must be contiguous");

    int64_t B = input.size(0);
    int64_t H = input.size(1);
    int64_t S = input.size(2);
    int64_t D = input.size(3);

    TORCH_CHECK(D % 2 == 0, "rotary_mul: last dimension D must be even");

    int64_t total_rows = B * H * S;
    int64_t total_elements = total_rows * D;
    int64_t half_d = D / 2;

    // --- Dtype flag ---
    int64_t dtype_flag = 0;  // fp32
    if (input.scalar_type() == at::kHalf) {
        dtype_flag = 1;
    } else if (input.scalar_type() == at::kBFloat16) {
        dtype_flag = 2;
    }

    // --- Rotary mode flag ---
    int64_t rotary_mode_flag = (rotary_mode == "interleave") ? 1 : 0;

    // --- Platform info ---
    auto ascendcPlatform = platform_ascendc::PlatformAscendCMgr::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
    if (coreNum <= 0) { coreNum = 32; }

    // --- UB tile size calculation ---
    uint64_t ubSize = 0;
    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    // UB budget: we need buffers for:
    //   inp_fp32, r1_fp32, r2_fp32, rot_fp32 (4x tile_rows * D * 4)
    //   + inQueue, outQueue (2x tile_rows * D * sizeof(dataType))
    //   + castBuf (if not fp32), evenBuf, oddBuf (if interleave)
    int64_t elemBytes = (dtype_flag == 0) ? 4 : 2;
    int64_t fp32PerElem = 4;
    int64_t numTbufs = (dtype_flag == 0) ? 4 : 5;
    if (rotary_mode_flag == 1) { numTbufs += 2; }

    // Max tile rows from UB: ubSize >= numTbufs * tile_rows * D * 4 + 2 * tile_rows * D * elemBytes
    // Simplification: ubSize >= tile_rows * D * (numTbufs * 4 + 2 * elemBytes)
    int64_t ubBudgetPerRow = D * (numTbufs * fp32PerElem + 2 * elemBytes);
    int64_t maxTileRows = static_cast<int64_t>(static_cast<double>(ubSize) * 0.85 / ubBudgetPerRow);
    // Clamp and align
    int64_t ub_tile_rows = std::min<int64_t>(128, std::max<int64_t>(16, maxTileRows));
    ub_tile_rows = (ub_tile_rows / 16) * 16;
    if (ub_tile_rows < 16) { ub_tile_rows = 16; }

    // --- Core-level tiling ---
    int64_t usedCoreNum = std::min(coreNum, CeilDiv(total_rows, ub_tile_rows));
    if (usedCoreNum < 1) { usedCoreNum = 1; }
    int64_t rows_per_core = CeilDiv(total_rows, usedCoreNum);

    // --- Output allocation ---
    at::Tensor output = at::empty_like(input);

    // --- EXEC_KERNEL_CMD: all parameters must be left-values ---
    int64_t total_rows_lv = total_rows;
    int64_t D_lv = D;
    int64_t half_d_lv = half_d;
    int64_t rows_per_core_lv = rows_per_core;
    int64_t ub_tile_rows_lv = ub_tile_rows;
    int64_t rotary_mode_lv = rotary_mode_flag;
    int64_t dtype_flag_lv = dtype_flag;
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    EXEC_KERNEL_CMD(rotary_mul, blockDim,
                    input, r1, r2, output,
                    total_rows_lv, D_lv, half_d_lv,
                    rows_per_core_lv, ub_tile_rows_lv,
                    rotary_mode_lv, dtype_flag_lv);

    return output;
}

}  // namespace ascend_kernel
